import javax.crypto.Cipher;  
import javax.crypto.spec.SecretKeySpec;  
import java.security.Key;  
import java.util.Base64;  

public class SecurePasswordStorage {  
    private static final String SECRET_KEY = "secureKey123";  
    private static final String ALGORITHM = "AES";  

    public static String encrypt(String plainText) throws Exception {  
        Key key = new SecretKeySpec(SECRET_KEY.getBytes(), ALGORITHM);  
        Cipher cipher = Cipher.getInstance(ALGORITHM);  
        cipher.init(Cipher.ENCRYPT_MODE, key);  
        return Base64.getEncoder().encodeToString(cipher.doFinal(plainText.getBytes()));  
    }  

    public static String decrypt(String encryptedText) throws Exception {  
        Key key = new SecretKeySpec(SECRET_KEY.getBytes(), ALGORITHM);  
        Cipher cipher = Cipher.getInstance(ALGORITHM);  
        cipher.init(Cipher.DECRYPT_MODE, key);  
        return new String(cipher.doFinal(Base64.getDecoder().decode(encryptedText)));  
    }  
}  
```  
**Comment:** This code securely stores a password using AES encryption with a secret key. It uses Base64 encoding for safe transmission and storage.  
